import argparse
import sys
from datetime import datetime

from .parse import parse_file
from .summary import summarise


def parse_date(s):
    """Parse strict YYYY-MM-DD, or raise ValueError."""
    d = None
    try:
        d = datetime.strptime(s, "%Y-%m-%d")
    except ValueError:
        pass
    if d is None or d.strftime("%Y-%m-%d") != s:
        raise ValueError(s)
    return d.date()


def main(argv=None) -> int:
    ap = argparse.ArgumentParser(prog="logsum", description="Summarise an access log.")
    ap.add_argument("logfile")
    ap.add_argument("--top", type=int, default=5, help="number of paths to list")
    ap.add_argument("--since", metavar="YYYY-MM-DD", help="only count requests on or after this date")
    ap.add_argument("--until", metavar="YYYY-MM-DD", help="only count requests on or before this date")
    a = ap.parse_args(argv)
    since = until = None
    bad = None
    for flag, raw in (("--since", a.since), ("--until", a.until)):
        if raw is None:
            continue
        try:
            d = parse_date(raw)
        except ValueError:
            bad = raw
            break
        if flag == "--since":
            since = d
        else:
            until = d
    if bad is not None:
        print(f"logsum: error: invalid date: {bad}", file=sys.stderr)
        return 2
    def in_range(r):
        d = r.ts.date()
        return (since is None or d >= since) and (until is None or d <= until)
    print(summarise([r for r in parse_file(a.logfile) if in_range(r)], top=a.top))
    return 0


if __name__ == "__main__":
    sys.exit(main())

